import{_ as s,C as i,o as t,c as n,a9 as o,b as l,w as a,a as c,E as d,a8 as h}from"./chunks/framework.BOiBTRPC.js";const b=JSON.parse('{"title":"Cloud Platforms","description":"GCP vs AWS vs Azure service maps, Databricks vs Snowflake architecture, and FinOps for data — the cloud decisions that actually show up in senior work.","frontmatter":{"title":"Cloud Platforms","description":"GCP vs AWS vs Azure service maps, Databricks vs Snowflake architecture, and FinOps for data — the cloud decisions that actually show up in senior work."},"headers":[],"relativePath":"cloud/index.md","filePath":"cloud/index.md"}'),u={name:"cloud/index.md"};function p(g,e,m,f,v,k){const r=i("Mermaid");return t(),n("div",null,[e[1]||(e[1]=o('<h1 id="cloud-platforms" tabindex="-1">Cloud Platforms <a class="header-anchor" href="#cloud-platforms" aria-label="Permalink to &quot;Cloud Platforms&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — Picking a cloud data stack is a multi-year, six-to-seven-figure commitment that is expensive to reverse. Senior engineers get asked three questions constantly: &quot;which managed service replaces this thing we self-host?&quot;, &quot;Databricks or Snowflake?&quot;, and &quot;why is the bill this big?&quot;. This track gives you the mental model to answer all three.</p></blockquote><h2 id="who-this-is-for" tabindex="-1">Who this is for <a class="header-anchor" href="#who-this-is-for" aria-label="Permalink to &quot;Who this is for&quot;">​</a></h2><ul><li>Data engineers joining a new cloud org who need to map &quot;the thing I knew&quot; to &quot;the thing they run&quot; fast.</li><li>Engineers preparing for senior/staff interviews where cloud architecture trade-offs come up.</li><li>Anyone who has inherited a platform bill and needs to find the levers, not just the line items.</li></ul>',4)),(t(),l(h,null,{default:a(()=>[d(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22Cloud%20Platforms%22%5D%20--%3E%20B%5B%22big-three%3Cbr%2F%3EService%20maps%20%2B%3Cbr%2F%3Ewarehouse%20compare%22%5D%0A%20%20%20%20A%20--%3E%20C%5B%22lakehouse-platforms%3Cbr%2F%3EDatabricks%20vs%20Snowflake%22%5D%0A%20%20%20%20A%20--%3E%20D%5B%22cost-architecture%3Cbr%2F%3EFinOps%20for%20data%22%5D%0A%20%20%20%20A%20--%3E%20E%5B%22platform-deep-dive%3Cbr%2F%3ENetworking%2C%20multi-region%3Cbr%2F%3E%26%20landing%20zones%22%5D%0A%20%20%20%20B%20--%3E%20C%0A%20%20%20%20C%20--%3E%20D%0A%20%20%20%20D%20--%3E%20E%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="chapters" tabindex="-1">Chapters <a class="header-anchor" href="#chapters" aria-label="Permalink to &quot;Chapters&quot;">​</a></h2><p><strong><a href="/Data-Knowledge/cloud/big-three.html">GCP vs AWS vs Azure</a></strong> — The service-by-layer map across all three clouds: storage, warehouse, lakehouse format, managed Spark/Flink, streaming bus, orchestration, ML platform. Then a deep compare of BigQuery vs Redshift vs Synapse — the pricing model differences that change how you design pipelines — plus the egress trap and the managed-vs-self-host decision.</p><p><strong><a href="/Data-Knowledge/cloud/lakehouse-platforms.html">Databricks vs Snowflake</a></strong> — The two lakehouse heavyweights dissected: how each is actually built (your object store + DBU compute vs centralized storage + credit compute), Delta vs Iceberg support, isolation and concurrency, governance via Unity Catalog vs Horizon, and the decision table for ML-heavy vs BI-heavy vs multi-cloud workloads. Includes the &quot;neither&quot; answer: Trino/Athena/DuckDB over Iceberg.</p><p><strong><a href="/Data-Knowledge/cloud/cost-architecture.html">Cost &amp; Decoupled Architecture</a></strong> — FinOps for data engineering. Cost attribution via tagging, storage lifecycle tiering, compute right-sizing (auto-suspend, serverless, spot), query cost control, the cost-per-useful-workload metric, a build-vs-buy framework, and a worked monthly cost sketch for a 100 TB / 1,000-queries-a-day workload.</p><p><strong><a href="/Data-Knowledge/cloud/platform-deep-dive.html">Networking, Multi-Region &amp; Landing Zones</a></strong> — The infrastructure layer under every platform decision: private connectivity (PrivateLink / Private Endpoint / Private Service Connect), VPC and subnet sizing that survives autoscale, landing-zone topology and account structure, multi-region DR with real RPO/RTO math, sovereignty constraints, and the commitment/egress pricing that decides whether the design is affordable.</p><h2 id="pareto-focus" tabindex="-1">Pareto focus <a class="header-anchor" href="#pareto-focus" aria-label="Permalink to &quot;Pareto focus&quot;">​</a></h2><p>The ideas in this track that carry the most weight:</p><ol><li><strong>Storage–compute decoupling</strong> is the single architectural decision that defines every modern cloud data platform — understand it once and every service comparison gets easier.</li><li><strong>The pricing meter shapes the design.</strong> Per-scan (BigQuery on-demand), per-second-credits (Snowflake), per-DBU (Databricks), per-node (Redshift provisioned) reward completely different pipeline patterns.</li><li><strong>Egress is the real lock-in.</strong> Storage is cheap; moving 100 TB out of a cloud is not. Design for the exit or accept the premium.</li><li><strong>Managed beats self-host until it doesn&#39;t</strong> — the crossover is ops burden vs. control, not sticker price.</li><li><strong>Open table formats are the escape hatch.</strong> Delta/Iceberg on your own bucket is what keeps both Databricks and Snowflake honest.</li><li><strong>Workload isolation is sold differently by every vendor</strong> — warehouses vs DBU clusters vs slots; know what concurrency actually costs on each.</li><li><strong>Cost is an architecture property, not a report.</strong> Tagging, lifecycle tiers, and auto-suspend are design decisions made before the first bill arrives.</li><li><strong>Private connectivity and DR are designed in, not tuned on.</strong> Private endpoints, subnet sizing, and multi-region RPO/RTO are provisioning-time decisions — get them wrong and the fix is a migration.</li></ol>',8))])}const y=s(u,[["render",p]]);export{b as __pageData,y as default};
